fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>
) {
    // All input arrays (including the output buffer) must have the same length.
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n,  "vals_2 must have the same length as vals_1");
    assert_eq!(conds_1.len(), n, "conds_1 must have the same length as vals_1");
    assert_eq!(conds_2.len(), n, "conds_2 must have the same length as vals_1");
    assert_eq!(avgs.len(), n,   "avgs must have the same length as vals_1");

    for i in 0..n {
        let use_first  = conds_1[i];
        let use_second = conds_2[i];
        // By assumption, at least one of use_first/use_second is true.
        avgs[i] = if use_first && use_second {
            // both true → integer average
            (vals_1[i] + vals_2[i]) / 2
        } else if use_first {
            // only first is true
            vals_1[i]
        } else {
            // only second is true
            vals_2[i]
        };
    }
}